import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.BAQ5ZYJQ.js";const g=JSON.parse('{"title":"Agents and keeping warm","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agents.md","filePath":"guide/agents.md","lastUpdated":1795072660000}'),i={name:"guide/agents.md"};function o(r,e,h,d,l,p){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="agents-and-keeping-warm" tabindex="-1">Agents and keeping warm <a class="header-anchor" href="#agents-and-keeping-warm" aria-label="Permalink to &quot;Agents and keeping warm&quot;">​</a></h1><p>Without errand, every command pays for its whole path again: an ssh login, a shell reading its rc file, an allocation, a container entered, a Python importing torch. errand pays once. The first command leaves small processes behind, <strong>agents</strong>, and the next commands go through them.</p><table tabindex="0"><thead><tr><th></th><th>each time, by hand</th><th>through agents</th></tr></thead><tbody><tr><td>a run on a machine over ssh</td><td>4–8 s</td><td>0.9–1.8 s</td></tr><tr><td>a session that imports torch (CUDA), with <code>Preload</code></td><td>2.9 s</td><td>1.5 s</td></tr></tbody></table><p>Nothing to declare: agents are how errand runs anything. They stop on their own when nobody uses them.</p><h2 id="where-they-run" tabindex="-1">Where they run <a class="header-anchor" href="#where-they-run" aria-label="Permalink to &quot;Where they run&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  here                          the machine Ssh leads to             the end of the stack</span></span>
<span class="line"><span>  ────                          ────────────────────────             ────────────────────</span></span>
<span class="line"><span>  errand ── hub ── one ssh ──── host agent ── the layers, once ───── environment agent ── sessions</span></span>
<span class="line"><span>  errand ──┘                    (push, pull, setup, probes)               (micromamba, container, …)</span></span></code></pre></div><ul><li><strong>The hub</strong>: one process here, per user. It keeps the connections to the agents open between commands, and several commands share them.</li><li><strong>A host agent</strong> on each machine errand reaches. It is started through one ssh; after that the pushes and pulls, the builds of <code>setup</code> and the probes all go through it. Nothing logs in again.</li><li><strong>An environment agent</strong> past the layers, with the environment&#39;s own interpreter: inside the micromamba env, the module, the container, the allocation. The layers are entered once, not once per command.</li></ul><p>Nothing is installed over there. errand&#39;s sources travel, and it finds a Python 3.8 or later to start on, or makes one for itself. → <a href="./layers/ssh#nothing-to-install-over-there">Nothing to install over there</a></p><p>Each agent also keeps track of everything it starts, on its own machine. That is what <a href="./status"><code>errand status</code></a> reads, and what lets the next agent clean up after one that died.</p><h2 id="kept-warm-for-a-while" tabindex="-1">Kept warm, for a while <a class="header-anchor" href="#kept-warm-for-a-while" aria-label="Permalink to &quot;Kept warm, for a while&quot;">​</a></h2><table tabindex="0"><thead><tr><th>what</th><th>stays up when unused</th><th>set by</th></tr></thead><tbody><tr><td>the hub, a host agent, an environment agent</td><td>15 minutes</td><td><code>ERRAND_HUB_KEEP_ALIVE</code> for the hub (seconds)</td></tr><tr><td>a Slurm allocation</td><td>1 minute by default; <code>0</code>: one job per command</td><td><a href="./layers/slurm"><code>Slurm( keep_alive = &quot;30m&quot; )</code></a></td></tr><tr><td>a Windows virtual machine</td><td>5 minutes</td><td><a href="./layers/windows"><code>Windows( keep = &quot;5m&quot; )</code></a></td></tr></tbody></table><p>An allocation kept warm means the next command that fits in it starts at once, without a new <code>sbatch</code> and without entering the layers again. &quot;Unused&quot; means no request and nothing running; an open connection does not count. So the chain comes down from the far end: the environment agent goes, then the node agent, the Slurm job ends, and finally the hub.</p><h2 id="warm-imports-preload" tabindex="-1">Warm imports: <code>Preload</code> <a class="header-anchor" href="#warm-imports-preload" aria-label="Permalink to &quot;Warm imports: \`Preload\`&quot;">​</a></h2><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">errand.envs[ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gpu&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> errand.Env( [ errand.Ssh( </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">host</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;gpu-box&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                                     errand.Micromamba( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;torch&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                                     errand.Preload( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;torch&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ) ] )</span></span></code></pre></div><p>With <a href="./layers/preload"><code>Preload</code></a> at the end of a stack, a session is a fork of a process that has already imported torch. Your project&#39;s own modules are always read again. Without the layer, every session is a fresh Python: your choice.</p><h2 id="giving-way" tabindex="-1">Giving way <a class="header-anchor" href="#giving-way" aria-label="Permalink to &quot;Giving way&quot;">​</a></h2><p>Something kept warm costs others while it waits: an idle VM holds cores and memory, a process with torch imported holds memory. Their claim in the <a href="./machine">machine&#39;s queue</a> <strong>gives way</strong>: a command that needs the room gets it at once, and the VM or the process goes. <code>errand queue</code> marks those claims as kept warm.</p><p>A warm Slurm allocation is never stretched. A command runs in it only if it fits: ranks, cores and cards per task, and <code>--time</code> within what the job has left. Otherwise it gets a job of its own. On a shared cluster, a short <code>keep_alive</code> is the polite choice.</p><h2 id="ctrl-c-stops-the-work" tabindex="-1">Ctrl-C stops the work <a class="header-anchor" href="#ctrl-c-stops-the-work" aria-label="Permalink to &quot;Ctrl-C stops the work&quot;">​</a></h2><p>Ctrl-C reaches the work wherever it runs: over ssh, in a container, in an allocation, in a Windows guest. The work gets an interrupt, then a terminate after 2 s, then a kill after 5 s, with everything in its process group. The agent over there does this, so it happens even if your connection is already gone. errand exits with code 130.</p><h2 id="a-real-terminal" tabindex="-1">A real terminal <a class="header-anchor" href="#a-real-terminal" aria-label="Permalink to &quot;A real terminal&quot;">​</a></h2><p><code>errand shell</code> gets a real terminal over there: a pty on Linux and macOS, a pseudo-console on Windows. Colours, line editing, full-screen programs, Ctrl-C as a key, window resizing.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cluster</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # a shell in the allocation, the container, the environment</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> win</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # cmd.exe in the Windows guest</span></span></code></pre></div><h2 id="listing-and-stopping-agents" tabindex="-1">Listing and stopping agents <a class="header-anchor" href="#listing-and-stopping-agents" aria-label="Permalink to &quot;Listing and stopping agents&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agents</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # the hub, and each agent it keeps a connection to</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agents</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gpu</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # those whose name contains &quot;gpu&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agents</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # all of them, and the hub</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  hub  pid 79636  up 3 s   ~/.cache/errand/hub-c81a3d1d455a</span></span>
<span class="line"><span>    lmo                              last used 0 s ago, 1 open; kept 15 min unused</span></span>
<span class="line"><span>    lmo:env-c81a3d1d455a-32772dfcfc  last used 0 s ago; kept 15 min unused</span></span></code></pre></div><p>Stopping goes from the far end: an environment before the machine or the allocation it runs in. An agent with something running is left alone and says so; <code>--force</code> stops it, and what it runs.</p><h2 id="watching-without-asking-again" tabindex="-1">Watching, without asking again <a class="header-anchor" href="#watching-without-asking-again" aria-label="Permalink to &quot;Watching, without asking again&quot;">​</a></h2><p><code>errand tui</code> does not ask each machine what runs there every few seconds: it subscribes to its agent, through the hub&#39;s link, and the agent says what changes as it changes -- a process that starts or ends ( within a fraction of a second ), the resources when they move by more than a few points, a run recorded in the history. Nothing crosses while nothing changes, but a sign of life every ten seconds. Over there, the agent looks at the dates of the agents&#39; directories twice a second ( a <code>stat</code> each ), and at the whole table every two seconds, sent only when it differs. An agent of an older errand is asked again and again, as before.</p><h2 id="what-stays-on-disk" tabindex="-1">What stays on disk <a class="header-anchor" href="#what-stays-on-disk" aria-label="Permalink to &quot;What stays on disk&quot;">​</a></h2><p>Under <code>~/.cache/errand</code> (or <code>$ERRAND_CACHE_DIR</code>), errand keeps only what is live: sockets, locks, pids, the records of running processes. Agents remove the directories nobody serves any more. What piles up belongs to the project, in its <code>errand-outputs/</code>:</p><table tabindex="0"><thead><tr><th>what</th><th>where</th><th>until</th></tr></thead><tbody><tr><td>a command&#39;s output, kept for <code>errand attach</code></td><td><code>errand-outputs/state/procs/</code></td><td>it is brought back</td></tr><tr><td>run records</td><td><code>errand-outputs/runs/</code></td><td>you remove them</td></tr><tr><td>Windows images</td><td><code>errand-outputs/builds/windows/</code></td><td>a newer one is ready</td></tr></tbody></table><p>→ <a href="./storage">Where errand writes</a></p><h2 id="modes" tabindex="-1">Modes <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;Modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th><code>ERRAND_AGENT</code></th><th></th></tr></thead><tbody><tr><td><code>hub</code></td><td>through the hub. The default on a terminal</td></tr><tr><td><code>direct</code></td><td>a connection that belongs to the command and closes with it. The default without a terminal (cron, CI)</td></tr></tbody></table><p>There is no mode without agents: every machine errand runs on has one, so what runs there is tracked, listed and stopped the same way everywhere.</p><p><code>ERRAND_WARM=0</code> starts every session anew, even with a <code>Preload</code>. <code>-v</code> prints every command errand starts, including those it hands to an agent. → <a href="./upkeep#when-something-breaks">When something breaks</a></p><p>The design: <a href="https://github.com/hleclerc/errand/blob/main/docs/adr/0005-the-local-side-orchestrates-agents-execute.md" target="_blank" rel="noreferrer">ADR 0005</a>, <a href="https://github.com/hleclerc/errand/blob/main/docs/adr/0008-nothing-runs-unowned.md" target="_blank" rel="noreferrer">ADR 0008</a>, <a href="https://github.com/hleclerc/errand/blob/main/docs/adr/0009-arrivals.md" target="_blank" rel="noreferrer">ADR 0009</a>.</p>`,38)])])}const u=t(i,[["render",o]]);export{g as __pageData,u as default};
